const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/vendors',
  qs: {
    view: 'SOME_STRING_VALUE',
    company_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[origin_id]': 'SOME_STRING_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[standard_cost_code_id][]': 'SOME_ARRAY_VALUE',
    'filters[trade_id][]': 'SOME_ARRAY_VALUE',
    'filters[id][]': 'SOME_ARRAY_VALUE',
    'filters[parent_id][]': 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/vendors?view=SOME_STRING_VALUE&company_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Borigin_id%5D=SOME_STRING_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Bstandard_cost_code_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Btrade_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bid%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bparent_id%5D%5B%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
